				stack.push_back(ent);
				t = *start;
				++start;
				break;
			}
			case lazy_entry::list_t:
			{
				if (t == 'e')
				{
					top->set_end(start);
					stack.pop_back();
					continue;
				}
				lazy_entry* ent = top->list_append();
				if (ent == 0) TORRENT_FAIL_BDECODE(boost::system::errc::not_enough_memory);
				stack.push_back(ent);
				break;
			}
			default: break;
		}

		--item_limit;
		if (item_limit <= 0) TORRENT_FAIL_BDECODE(bdecode_errors::limit_exceeded);

		top = stack.back();
		switch (t)
		{
			case 'd':
				top->construct_dict(start - 1);
				continue;
			case 'l':
				top->construct_list(start - 1);
				continue;
			case 'i':
			{
				char const* int_start = start;
				start = find_char(start, end, 'e');
				top->construct_int(int_start, start - int_start);
				if (start == end) TORRENT_FAIL_BDECODE(bdecode_errors::unexpected_eof);
				TORRENT_ASSERT(*start == 'e');
				++start;
				stack.pop_back();
				continue;
			}
			default:
			{
				if (!numeric(t))
					TORRENT_FAIL_BDECODE(bdecode_errors::expected_value);

				boost::int64_t len = t - '0';
				bdecode_errors::error_code_enum e = bdecode_errors::no_error;
				start = parse_int(start, end, ':', len, e);
				if (e)
					TORRENT_FAIL_BDECODE(e);

				// remaining buffer size excluding ':'
				const ptrdiff_t buff_size = end - start - 1;
				if (len > buff_size)
					TORRENT_FAIL_BDECODE(bdecode_errors::unexpected_eof);
				if (len < 0)
					TORRENT_FAIL_BDECODE(bdecode_errors::overflow);

				++start;
				if (start == end) TORRENT_FAIL_BDECODE(bdecode_errors::unexpected_eof);
				top->construct_string(start, int(len));
				stack.pop_back();
				start += len;
				continue;
			}
		}
		return 0;
	}
	return 0;
}

GetCode_(gdIOCtx *fd, CODE_STATIC_DATA *scd, int code_size, int flag, int *ZeroDataBlockP)
{
	int i, j, ret;
	unsigned char count;

	if(flag) {
		scd->curbit = 0;
		scd->lastbit = 0;
		scd->last_byte = 0;
		scd->done = FALSE;
		return 0;
	}

	if((scd->curbit + code_size) >= scd->lastbit) {
		if(scd->done) {
			if(scd->curbit >= scd->lastbit) {
				/* Oh well */
			}
			return -1;
		}

		scd->buf[0] = scd->buf[scd->last_byte - 2];
		scd->buf[1] = scd->buf[scd->last_byte - 1];

		if((count = GetDataBlock(fd, &scd->buf[2], ZeroDataBlockP)) <= 0) {
			scd->done = TRUE;
		}

		scd->last_byte = 2 + count;
		scd->curbit = (scd->curbit - scd->lastbit) + 16;
		scd->lastbit = (2 + count) * 8;
	}

	ret = 0;
	for (i = scd->curbit, j = 0; j < code_size; ++i, ++j) {
		ret |= ((scd->buf[i / 8] & (1 << (i % 8))) != 0) << j;
	}

	scd->curbit += code_size;

	return ret;
}

GetCode_(gdIOCtx *fd, CODE_STATIC_DATA *scd, int code_size, int flag, int *ZeroDataBlockP)
{
